s.listen(0, '127.0.0.1', () => {
  const c = net.connect(s.address().port, '127.0.0.1', () => c.write('GET http://[ HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n'));
  let out = ''; c.on('data', (d) => out += d); c.on('close', () => { console.log('RESPONSE', out.split('\r\n')[0]); process.exit(0); });
});
EOF
